svg.script:
//!export-start
let _ps_medium = 'normal';
let _ps_lineType = 'fluid';
let _ps_fluid = '';
//!export-end

var __busyUntil = 0;

function toBool(v) {
    if (v === true || v === 1) return true;
    var s = String(v).toLowerCase();
    return s === 'true' || s === '1' || s === 'on';
}

function toNum(v) {
    if (v === true || v === 'true') return 1;
    if (v === false || v === 'false') return 0;
    var n = parseFloat(v);
    return isNaN(n) ? 0 : n;
}

function apply() {
    var preview = document.getElementById('ob_preview');
    if (preview && preview.parentNode) { preview.parentNode.removeChild(preview); }
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.medium = String(_ps_medium);
    el.lineType = String(_ps_lineType);
    if (String(_ps_fluid)) { el.style.setProperty('--automation-fresh-water', 'var(--automation-medium-' + String(_ps_fluid) + ')'); } else { el.style.removeProperty('--automation-fresh-water'); }
}

function putValue(id, value) {
    if (id === '_ps_medium') { _ps_medium = String(value); }
    if (id === '_ps_lineType') { _ps_lineType = String(value); }
    if (id === '_ps_fluid') { _ps_fluid = String(value); }
    apply();
}

function postValue(id, value) {
    // replaced at runtime: writes value to the tag bound to "id"
}

apply();
